static inline int par8(unsigned x){ x^=x>>4; x^=x>>2; x^=x>>1; return x&1; }
static inline unsigned g(unsigned a,unsigned b,unsigned x){ unsigned t=(a+b+x)&255; return ((t<<2)|(t>>6))&255; }
static void fwht(int64_t *a,int n){ for(int len=1;len<n;len<<=1) for(int i=0;i<n;i+=len<<1) for(int j=0;j<len;j++){ int64_t u=a[i+j],v=a[i+j+len]; a[i+j]=u+v; a[i+j+len]=u-v; } }

typedef struct { double c; int x, mc, ma, mb; } Rec;
int main(void){
  Rec best[40]; int nb=0;
  for(int x=0;x<=1;x++){
    for(int mc=0;mc<256;mc++){
      static int64_t f[1<<16];
      for(int idx=0;idx<65536;idx++){
        int a=idx&255,b=(idx>>8)&255;
        f[idx]=par8(mc&g(a,b,x)) ? -1 : 1;
