        else { int w=0; for(int i=1;i<40;i++){ double ai=best[i].c<0?-best[i].c:best[i].c, aw=best[w].c<0?-best[w].c:best[w].c; if(ai<aw) w=i; } double aw=best[w].c<0?-best[w].c:best[w].c; if(ac>aw) best[w]=(Rec){c,x,mc,ma,mb}; }
